def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r0 in range(h):
        for r1 in range(r0 + 4, h):
            c = 0
            while c < w:
                color = grid[r0][c]
                if all(grid[r][c] == color for r in range(r0, r1 + 1)):
                    start = c
                    while c < w and all(grid[r][c] == color for r in range(r0, r1 + 1)):
                        c += 1
                    if c - start >= 5:
                        for r in range(r0, r1 + 1):
                            for x in range(start, c):
                                out[r][x] = 4
                else:
                    c += 1
    return out
